const size_t nlocales = sizeof(locales) / sizeof(locales[0]);

const struct locale *
locale_find(const char *tag)
{
	size_t i;

	for (i = 0; tag && i < nlocales; i++)
		if (!strcmp(locales[i].tag, tag))
			return &locales[i];
	return &locales[0];
}
